import React, { useState, useEffect } from 'react';
import {
  TextField,Button,Container,Typography,Paper,Table,TableBody,TableCell,
  TableContainer,TableHead,TableRow,Chip,Box,Alert,AppBar,Toolbar,
  CssBaseline,useMediaQuery,Slide,Zoom,Grid,ThemeProvider,createTheme,
} from '@mui/material';
import { green, red, blue, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: {
      main: '#0D47A1', // Dark Blue
    },
    secondary: {
      main: '#FF6F00', // Amber
    },
    background: {
      default: '#f4f6f8',
      paper: '#ffffff',
    },
    error: {
      main: '#D32F2F',
    },
  },
  typography: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    h4: {
      fontWeight: 700,
      letterSpacing: '0.1em',
    },
    h5: {
      fontWeight: 600,
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
    },
  },
  shape: {
    borderRadius: 12,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          boxShadow: '0 4px 12px rgba(255, 111, 0, 0.3)',
          transition: 'all 0.3s ease',
          '&:hover': {
            boxShadow: '0 6px 20px rgba(255, 111, 0, 0.5)',
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          boxShadow: '0 10px 30px rgba(0,0,0,0.1)',
          padding: '32px',
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);

  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://localhost:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    // Clear any monitoring cache or localStorage on mount
    localStorage.removeItem('monitoringStatus');
    localStorage.removeItem('threatDetected');
    localStorage.removeItem('threatLogs');

    const interval = setInterval(async () => {
      try {
        const response = await fetch('http://localhost:5001/status');
        const data = await response.json();
        setMonitoringStatus(data.status);
        setThreatDetected(data.threat_detected);

        const logsResponse = await fetch('http://localhost:5001/threat_logs');
        const logsData = await logsResponse.json();
        const cleanedLogs = logsData.map(log => {
          let cleanedWebsite = log.website;
          if (cleanedWebsite.startsWith('http://')) {
            cleanedWebsite = cleanedWebsite.slice(7);
          } else if (cleanedWebsite.startsWith('https://')) {
            cleanedWebsite = cleanedWebsite.slice(8);
          }
          return { ...log, website: cleanedWebsite };
        });
        setThreatLogs(cleanedLogs);
      } catch (error) {
        setMonitoringStatus('Error');
        setThreatDetected(false);
        setThreatLogs([]);
      }
    }, 5000);

    // Stop monitoring on page unload or component unmount
    const handleBeforeUnload = async () => {
      try {
        await fetch('http://localhost:5001/stop_monitoring', { method: 'POST' });
      } catch (error) {
        // Ignore errors
      }
    };
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      clearInterval(interval);
      window.removeEventListener('beforeunload', handleBeforeUnload);
      // Also stop monitoring on component unmount
      fetch('http://localhost:5001/stop_monitoring', { method: 'POST' }).catch(() => {});
    };
  }, []);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring':
        return green[600];
      case 'Idle':
        return grey[600];
      case 'Starting':
        return blue[600];
      default:
        return grey[600];
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <AppBar position="static" color="primary" elevation={8} sx={{ mb: 6 }}>
        <Toolbar>
          <Typography variant={isMobile ? 'h6' : 'h4'} component="div" sx={{ flexGrow: 1, fontWeight: 'bold', letterSpacing: 4 }}>
            Cyber Threat Detection System
          </Typography>
        </Toolbar>
      </AppBar>
      <Container maxWidth="lg">
        <Grid container spacing={6}>
          <Grid item xs={12} md={5}>
            <Paper>
              <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', mb: 3 }}>
                Monitor a Website
              </Typography>
              <Box
                component="form"
                onSubmit={(e) => {
                  e.preventDefault();
                  startMonitoring();
                }}
                sx={{
                  display: 'flex',
                  gap: 2,
                  flexWrap: 'wrap',
                  justifyContent: 'center',
                  alignItems: 'center',
                }}
              >
                <TextField
                  label="Website URL"
                  variant="outlined"
                  fullWidth
                  value={website}
                  onChange={(e) => setWebsite(e.target.value)}
                  required
                  sx={{ flexGrow: 1, minWidth: 250 }}
                />
                <Button variant="contained" color="secondary" type="submit" sx={{ minWidth: 160, py: 1.8 }}>
                  Start Monitoring
                </Button>
              </Box>
              {message && (
                <Zoom in={Boolean(message)}>
                  <Alert severity="info" sx={{ mt: 3, borderRadius: 2, fontWeight: 'medium' }}>
                    {message}
                  </Alert>
                </Zoom>
              )}
              <Box sx={{ mt: 5, textAlign: 'center' }}>
                <Typography variant="h6" component="span" sx={{ fontWeight: 'medium' }}>
                  Status:
                </Typography>
                <Chip
                  label={monitoringStatus}
                  sx={{
                    ml: 1,
                    bgcolor: threatDetected ? red[700] : getStatusColor(monitoringStatus),
                    color: 'white',
                    fontWeight: 'bold',
                    fontSize: 16,
                    px: 2,
                    py: 0.5,
                    borderRadius: 2,
                    boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                  }}
                />
                {threatDetected && (
                  <Slide direction="down" in={threatDetected} mountOnEnter unmountOnExit>
                    <Alert severity="error" sx={{ mt: 3, borderRadius: 3, fontWeight: 'bold', fontSize: 16 }}>
                      Threat Detected on the website!
                    </Alert>
                  </Slide>
                )}
              </Box>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Paper>
              <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', mb: 3 }}>
                Threat Detection Log
              </Typography>
              {threatLogs.length === 0 ? (
                <Typography variant="body1" color="text.secondary" align="center" sx={{ fontStyle: 'italic' }}>
                  No threats detected yet.
                </Typography>
              ) : (
                <TableContainer sx={{ maxHeight: 400, overflowY: 'auto', width: '100%' }}>
                  <Table stickyHeader sx={{ minWidth: '100%' }} aria-label="threat detection log table">
                    <TableHead>
                      <TableRow>
                        <TableCell sx={{ fontWeight: 'bold' }}>Timestamp</TableCell>
                        <TableCell sx={{ fontWeight: 'bold' }}>Website</TableCell>
                        <TableCell sx={{ fontWeight: 'bold' }}>Threat Name</TableCell>
                        <TableCell sx={{ fontWeight: 'bold' }}>Message</TableCell>
                        <TableCell sx={{ fontWeight: 'bold' }}>Solution</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {threatLogs.map((log, index) => (
                        <TableRow key={index} hover sx={{ '&:hover': { backgroundColor: grey[100] } }}>
                          <TableCell>{log.timestamp}</TableCell>
                          <TableCell>{log.website}</TableCell>
                          <TableCell>{log.threat_name}</TableCell>
                          <TableCell>{log.message}</TableCell>
                          <TableCell>{log.solution}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
            </Paper>
          </Grid>
        </Grid>
        <Box component="footer" sx={{ mt: 8, py: 3, textAlign: 'center', bgcolor: grey[200], borderRadius: 2 }}>
          <Typography variant="body2" color="text.secondary">
            &copy; {new Date().getFullYear()} Cyber Threat Detection System. All rights reserved.
          </Typography>
        </Box>
      </Container>
    </ThemeProvider>
  );
}

export default App;
